import {profileQuestions,orderedProfileQuestions,profileResume,profileComplete,questionAnswered,broadSuggestions,broadReasons,fieldGroups,fieldCareers,professionSuggestions,skillQuestions,skillLabels,skillResponseOptions,skillExperienceFamiliar,skillExperienceNeedsSupport,contextQuestions,PROFILE_VERSION,depthComplete,journeyInterestPicture,journeyFieldConnection,profileSectionStarts} from './profile-journey.js?v=0.31.0';
