const a=(route,text,secondary=false)=>`<a class="button ${secondary?'secondary':''}" href="#/${route}">${text}</a>`;
const b=(action,text,attrs='',secondary=false)=>`<button class="button ${secondary?'secondary':''}" data-action="${action}" ${attrs}>${text}</button>`;
const more=(title,body)=>`<details class="more-info"><summary>${title}</summary><div>${body}</div></details>`;
const intro=(small,title,copy='')=>`<div class="page-intro"><div><span class="eyebrow">${small}</span><h1>${title}</h1>${copy?'<p>'+copy+'</p>':''}</div></div>`;
const questionIntro=(title)=>`<header class="question-intro"><h1>${h(title)}</h1></header>`;
export {fieldGlyph} from './glyphs.js?v=0.31.8';
import {glyph,fieldGlyph,discoveryIllustration} from './glyphs.js?v=0.31.8';
export function journeyProgress(stage){return `<nav class="journey-progress" aria-label="Your guide"><span>${['Picture your life','Your interests','Explore careers','Optional field surveys','My Plan'].map((t,i)=>`<i class="${i===stage?'current':i<stage?'done':''}"><b>${i<stage?'✓':i+1}</b>${t}</i>`).join('')}</span></nav>`;}
export function profileJourneyHome(s){const j=s.profileJourney,ready=s.guide.completed&&s.guide.primaryCareer;return `<section class="fieldguide-hero"><div class="hero-copy"><span class="eyebrow hero-eyebrow">${glyph('explore')}YOUR NEXT CHAPTER</span><h1>A future that<br>feels like you.</h1><p>Picture your life. Find work you care about.<br>Build a plan you can change.</p><div class="hero-primary">${ready?a('plan','Open My Plan →')+b('journey-begin','Revisit my guide','',true):b('journey-begin',j?.started?'Continue my guide →':'Start my guide →')}</div><p class="hero-save-note">Your progress saves as you go.</p></div><div class="hero-compass">${discoveryIllustration()}<span class="compass-note">Many possibilities.<br>Your own direction.</span></div></section><ol class="journey-map"><li><b>${glyph('home')}</b><span>Picture your life</span></li><li><b>${glyph('interests')}</b><span>Discover your interests</span></li><li><b>${glyph('explore')}</b><span>Explore the work</span></li><li><b>${glyph('plan')}</b><span>Make your plan</span></li></ol><section class="career-library-door"><div><span class="overline">JUST LOOKING AROUND?</span><h2 class="library-door-title">${glyph('library')}The career library.</h2><p>Learn about careers and save things to read. No questionnaire or personal plan.</p></div><div>${a('learn/college','Careers with college →',true)}${a('learn/training','Careers without college →',true)}</div></section><details class="more-info home-details"><summary>About this guide</summary><p>Start by picturing your lifestyle, then discover your interests and explore careers across every field. Your budget helps compare college, graduate and other training routes. Detailed field surveys remain optional.</p><a href="#/journey/research">What shaped this guide →</a><p><button class="text-link" data-action="restart-options">Restart or reset my guide →</button></p></details>`;}


function profileIntroductionPage(s){const revisiting=s.profileJourney.introSeen||profileQuestions.some(q=>questionAnswered(s,q));return `${journeyProgress(1)}<section class="profile-introduction"><header><span class="intro-glyph">${glyph('interests')}</span><h1>Start with what you’d enjoy.</h1></header><p class="profile-intro-lead">The next questions describe different kinds of work. Tell us how much you’d enjoy each activity.</p><div class="profile-intro-points"><p><strong>Just your interest.</strong> Set aside skill, education, training, and pay.</p><p><strong>Imagine giving it a try.</strong> You don’t need experience. There are no right or wrong answers.</p></div><p>Next come everyday-work choices and what matters to you. You can add your experience later.</p><div class="guide-actions"><a href="#/journey/lifestyle-summary">← Back</a>${b('journey-profile-start',revisiting?'Back to questions →':'Let’s start →')}</div>${more('About these questions',`<p>First comes the O*NET® Interest Profiler. Then a short set of Fieldguide questions explores everyday work and priorities. Experience and extra work preferences are optional.</p><p>${h(onetInstrument.attribution)}</p><p>Official item wording, response labels, and question sequence are preserved. Fieldguide provides the presentation and separate follow-up guidance; it is not endorsed by USDOL/ETA.</p><p><a href="${onetInstrument.licenseURL}" target="_blank" rel="noopener">CC BY-ND 4.0 license</a> · <a href="${onetInstrument.sourceURL}" target="_blank" rel="noopener">Official item source</a></p>${s.profileJourney.legacyAssessment?'<p>Your earlier answers and plan stay saved separately.</p>':''}`)}${more('Question options','<p>The guide focuses follow-ups on fields you like. You can answer questions about every field instead.</p>'+b('journey-question-mode',s.profileJourney.questionMode==='focused'?'Answer about every field':'Use focused follow-ups','',true))}</section>`;}
function profileFollowupIntroductionPage(){return `${journeyProgress(1)}<section class="profile-introduction profile-followup-introduction"><header><span class="intro-glyph">${glyph('explore')}</span><h1>Let’s get more specific.</h1></header><p>You’ve finished the O*NET interest questions. Next, we’ll explore everyday work in more detail.</p><p>The choices now run from <strong>“Really not for me”</strong> to <strong>“I’d love this.”</strong> Keep focusing on what you’d enjoy—not your skills, training, or pay.</p><div class="guide-actions">${b('journey-followups-back','← Back','',true)}${b('journey-followups-start','Keep going →')}</div></section>`;}
function profileSectionIntroductionPage(kind,s){const content={skill:{icon:'interests',title:'What have you tried?',body:'<p>Next, tell us what you can do today. Think about school, home, hobbies, or helping someone.</p><p>Choose the statement that fits best—from <strong>“This is new to me”</strong> to <strong>“I could show someone else how.”</strong> Skills grow with practice.</p>'},values:{icon:'target',title:'What matters most to you?',body:'<p>Next, choose what you most want from work—like learning, helping people, or a steady future.</p><p>Pick <strong>up to three</strong> things that matter most to you. Tap a choice again to remove it.</p>'},context:{icon:'plan',title:'Picture a working day.',body:'<p>Next, tell us how you’d like to work and which education or training routes you’d consider.</p><p>Choose what fits. Some questions allow <strong>more than one choice.</strong> It’s fine to still be exploring.</p>'}}[kind];if(kind==='context'&&!s.profileJourney.reviewSection&&s.profileJourney.questionMode!=='all'){content.title='How would you like to learn?';content.body='<p>Choose the education or training routes you would consider. You can pick more than one.</p><p>You can add work-style preferences later.</p>';}return `${journeyProgress(1)}<section class="profile-introduction profile-followup-introduction"><header><span class="intro-glyph">${glyph(content.icon)}</span><h1>${content.title}</h1></header>${content.body}<div class="guide-actions">${b('journey-section-back','← Back',`data-kind="${kind}"`,true)}${b('journey-section-start','Keep going →',`data-kind="${kind}"`)}</div></section>`;}
function professionIntroductionPage(s){const f=careerFamilies.find(f=>f.id===s.profileJourney.family);if(!f)return pathwaysPage(s);return `${journeyProgress(3)}<section class="profile-introduction profile-followup-introduction"><header><span class="intro-glyph">${glyph(f.id)}</span><h1>Let’s look closer at the jobs.</h1></header><p>Next, explore the tasks and training in <strong>${h(f.title)}.</strong> Your choices will help us compare jobs in this field.</p><p>Choose any parts you’d like to try and any training routes you’d consider. You can <strong>skip a question</strong> if nothing fits.</p><div class="guide-actions">${a('journey/pathways','← Back',true)}${b('journey-profession-start','Keep going →')}</div></section>`;}
function profileQuestionPage(s){const j=s.profileJourney,q=orderedProfileQuestions(s)[j.index]||profileQuestions[0],answered=questionAnswered(s,q),momentum=profileMomentum(s);let body='';if(['interest','pathway'].includes(q.kind)){const opts=q.kind==='interest'?onetResponseOptions:preferenceOptions.filter(o=>Number.isInteger(o.value)),value=q.kind==='interest'?profileInterestAnswer(s,q):j.fieldPreferences[q.id];body=`<div class="profile-answer-grid">${opts.map(o=>b('journey-answer',h(o.label),`data-question="${q.id}" data-value="${o.value}" aria-pressed="${value===o.value}" data-choice-tone="${o.value}"`)).join('')}</div>`;}
 if(q.kind==='skill'){const v=j.skills[q.id]||{};body=`<fieldset><legend>Which sounds most like you?</legend><div class="profile-answer-grid skill-response-options">${skillResponseOptions.map(o=>b('journey-answer',h(o.label),`data-question="${q.id}" data-value="${o.id}" aria-pressed="${v.level===o.id}"`,true)).join('')}</div></fieldset>${!v.level&&questionAnswered(s,q)?more('Your earlier answer is saved','<p>You previously answered the experience and confidence questions. Choose above to update your response.</p>'):''}`;}
 if(q.kind==='values')body=`<p class="choice-instruction">Choose up to three.</p><div class="profile-multi-grid">${priorities.map(p=>b('journey-value',h(p.title),`data-id="${p.id}" aria-pressed="${s.priorities.includes(p.id)}"`,true)).join('')}</div>`;
 if(q.kind==='context')body=`${q.multi?'<p class="choice-instruction">Choose any that fit.</p>':''}<div class="profile-answer-grid">${q.options.map(([id,t])=>b(q.multi?'journey-context-toggle':'journey-answer',h(t),`data-question="${q.id}" data-value="${id}" aria-pressed="${q.multi?(j.answers[q.id]||[]).includes(id):j.answers[q.id]===id}"`,true)).join('')}</div>`;
 const automatic=['interest','pathway','skill'].includes(q.kind)||q.kind==='context'&&!q.multi,reviewing=!!j.reviewSection,lastVisible=profileNavigationQuestions(s).at(-1)?.id===q.id;
 return `${journeyProgress(1)}<div class="question-toolbar"><button class="text-link" data-action="journey-instructions">How to decide</button><a href="#/overview">Save & pause</a></div>${questionIntro(q.prompt)}<section class="profile-question ${!automatic?'multi-question':''}"><div class="profile-progress-label"><span>${h(momentum.label)}</span><span ${momentum.boost?'class="progress-cheer" data-profile-cheer':''}>${momentum.boost?h(momentum.boost.badge):'Part '+momentum.part+' of '+momentum.parts}</span></div><div class="quiet-progress" role="progressbar" aria-label="${h(momentum.label)} progress" aria-valuemin="0" aria-valuemax="${momentum.total}" aria-valuenow="${momentum.done}" aria-valuetext="${momentum.done} of ${momentum.total} completed in this part"><i data-profile-progress data-profile-kind="${momentum.kind}" data-profile-percent="${momentum.percent}" style="width:${momentum.percent}%"></i></div>${body}${momentum.boost?`<aside class="profile-boost boost-${momentum.boost.tone}" data-profile-boost="${momentum.boost.id}" role="status" aria-live="polite" aria-atomic="true"><span class="boost-glyph">${glyph(momentum.boost.icon)}</span><div><strong>${h(momentum.boost.title)}</strong><p>${h(momentum.boost.copy)}</p></div></aside>`:''}<div class="guide-actions ${!automatic?'mobile-step-actions':''}">${reviewing?b('journey-profile-back','← Back','',true):j.index?b('journey-profile-back','← Back','',true):a(j.introSeen?'journey/lifestyle-summary':'journey/profile-intro','← Back',true)}${automatic?'':b('journey-profile-next',lastVisible?(reviewing?'Done →':'See my pathways →'):q.kind==='values'&&!s.priorities.length||q.kind==='context'&&q.multi&&!answered?'Skip for now →':'Next →',`id="journey-profile-next" ${q.kind==='skill'&&!answered?'disabled':''}`)}</div>${reviewing?'<p>'+b('journey-review-done','Save & return to my profile','',true)+'</p>':momentum.complete?'<p>'+a('journey/pathways','Back to pathway suggestions',true)+'</p>':''}</section>`;}
const adjacentCopy={technology:'A related option: digital design and building useful tools.',building:'A related option: product, building, and spatial design.',science:'A related option: investigate living systems and evidence.',education:'A related option: explain ideas and help others learn.',trades:'A related option: make, install, and repair useful things.',health:'A related option: combine investigation with helping people.',business:'A related option: understand audiences and organize ideas.',services:'A related option: practical work with people.','transportation-production':'A related option: equipment, production, and practical systems.','sales-office':'A related option: customers, communication, and organization.'};
const exampleRoles={creative:'Graphic design · Product design · Writing',technology:'Software · Data · Cybersecurity',health:'Medicine · Dentistry · Nursing',science:'Biology · Environment · Chemistry',building:'Engineering · Architecture',trades:'Electrical · Plumbing · Carpentry',business:'Business · Finance · Law',services:'Food · Hospitality · Personal care',education:'Teaching · Learning support','public-safety':'Fire & rescue · Public safety','transportation-production':'Transport · Production · Maintenance','sales-office':'Sales · Office & customer support'};
function patternDetails(s,c){return more('More info · your answers',`<h4>Your interests & work preferences</h4><p>We use all six interest scores and your work choices.</p><b>Your pattern across answers</b><ul>${c.reasons.map(t=>'<li>'+h(t)+'</li>').join('')}</ul><ul>${c.focused.items.map(q=>'<li>'+h(q.prompt)+' — '+h(preferenceOptions.find(o=>o.value===q.value)?.label||'Not answered')+'</li>').join('')}</ul><p>This describes interests, not ability or your chance of success.</p>`);}

function earlierActivityAnswers(s){if(!s.profileJourney.legacyAssessment)return '';const rows=legacyInterestQuestions.map(q=>({q,value:profileInterestAnswer(s,q)})).filter(x=>x.value!==undefined);return more('Your earlier activity answers',`<p>These original Fieldguide answers are saved separately. They are not converted into O*NET assessment scores.</p><ul>${rows.map(({q,value})=>'<li>'+h(q.text)+' — '+h(preferenceOptions.find(o=>o.value===value)?.label||'Not sure')+'</li>').join('')}</ul>`);}
export function interestProfileChart(s){const p=journeyInterestPicture(s);return `<section class="riasec-profile"><h3>Your six-part interest profile</h3>${!p.complete?'<p>Finish the O*NET questions to see all six scores. Earlier custom answers stay separate.</p>':`<div class="riasec-bars">${riasecOrder.map(t=>`<div><span>${h(riasecNames[t])}</span><div class="riasec-track" role="meter" aria-label="${h(riasecNames[t])} interest" aria-valuemin="0" aria-valuemax="40" aria-valuenow="${p.groups[t].raw}"><i style="width:${p.groups[t].raw/40*100}%"></i></div><strong>${p.groups[t].raw} / 40</strong></div>`).join('')}</div><p>These scores show interests, not skills.</p>${p.flat?'<p>You rated every interest equally. No one field stands out yet.</p>':p.nearFlat?'<p>Your scores are close. Try a few kinds of work before choosing.</p>':''}`}</section>`;}
function preferenceNotice(c){if(c.conflicting)return `<aside class="preference-conflict"><strong>You disliked some parts of this work.</strong>${more('More info · what did not fit','<ul>'+c.focused.concerns.map(q=>'<li>'+h(q.summary)+'</li>').join('')+'</ul><p>'+(c.interestSupported?'Your wider interests fit, but some daily tasks do not.':'You can still explore this field, but it is not a recommendation.')+'</p>')}</aside>`;if(!c.focused.confirmed)return '<p class="preference-open">Try a few tasks before choosing this field.</p>';if(!c.interestSupported)return '<p class="preference-open">You liked the tasks. Your wider interests are different.</p>';return '';}
function familyCard(s,f,featured=false){const c=journeyFieldConnection(s,f.id);return `<article class="pathway-card ${featured?'pathway-supported':c.conflicting?'pathway-conflict':''}"><header class="field-card-heading">${fieldGlyph(f.id)}<h3>${h(f.title)}</h3></header><div>${!featured?'<p class="card-kicker">'+(c.conflicting?'Some parts do not fit':c.focused.confirmed&&!c.interestSupported?'Tasks you liked':'Your choice to explore')+'</p>':''}<p>${h(exampleRoles[f.id]||f.copy)}</p>${featured?'<p>Your interests and work choices both fit this field.</p>':''}${preferenceNotice(c)}${patternDetails(s,c)}</div>${b('journey-family',featured?'Explore this pathway →':'Explore this field →',`data-id="${f.id}"`)}</article>`;}
function profileSnapshot(s){const answered=skillQuestions.filter(q=>questionAnswered(s,{...q,kind:'skill'})),strengths=skillQuestions.filter(q=>skillExperienceFamiliar(s.profileJourney.skills[q.id]));return interestProfileChart(s)+earlierActivityAnswers(s)+(answered.length?`<div class="profile-snapshot"><article><span>YOUR EXPERIENCE</span><h3>${strengths.length?'Things you have tried':'Starting with practice'}</h3><p>${strengths.length?strengths.map(q=>h(skillLabels[q.id])).join(' · '):'Small activities can help you find what you enjoy doing.'}</p></article></div>`:'');}

function pathwaysPage(s){const suggestions=broadSuggestions(s),n=suggestions.fields.length,title=n===0?(suggestions.workFields.length?'Start with work you enjoy.':'Let’s find work you want to try.'):n===1?'One pathway stands out.':n===2?'Two pathways worth exploring.':'Pathways worth exploring.';return `${journeyProgress(2)}${broadExplorationEntry()}${intro('YOUR STARTING DIRECTIONS',title,n?'Based on your interests and the work you liked.':suggestions.workFields.length?'Your daily-work choices give us a useful starting point. Explore a field to look closer at careers.':'There is no clear recommendation yet. Choose a field below to learn what the work is like.')}${n?'<div class="pathway-trio">'+suggestions.fields.map(f=>familyCard(s,f,true)).join('')+'</div>':'<p class="profile-note">You do not need to choose a career. Start with one small experience that interests you.</p>'}${suggestions.workFields.length?'<section class="work-led-pathways"><h2>Work you said you would enjoy.</h2><p>You liked these tasks. Your wider interests are less similar.</p><div class="pathway-trio">'+suggestions.workFields.map(f=>familyCard(s,f)).join('')+'</div></section>':''}${more('Your profile, in a few words',profileSnapshot(s)+`<p><strong>What matters to you:</strong> ${s.priorities.map(id=>h(priorities.find(p=>p.id===id)?.title)).join(' · ')||'Still exploring'}</p><p>Lifestyle and income do not change your interest scores.</p><p>Experience and extra work preferences are optional. Add them anytime.</p>${a('journey/profile-review','Review or add answers',true)}`)}<section class="guide-input-panel"><h2>Explore more college careers.</h2><p>Find possibilities across 404 sourced degree-career profiles, using your underlying interests. You do not need to know the job first.</p><a class="text-link" href="#/degree-careers">Explore college & graduate careers →</a></section><section class="other-pathways"><h2>${n||suggestions.workFields.length?'Choose another field.':'Pick something to explore.'}</h2><p>You can explore any field.</p>${fieldGroups.map(group=>{const fields=group.families.filter(id=>![...suggestions.fields,...suggestions.workFields].some(f=>f.id===id)).map(id=>careerFamilies.find(f=>f.id===id));return fields.length?more(h(group.title),'<div class="field-group-grid">'+fields.map(f=>familyCard(s,f)).join('')+'</div>'):'';}).join('')}</section><div class="guide-actions">${a('journey/profile-review','← My profile',true)}${a('journey/lifestyle-summary','Review my lifestyle',true)}</div>`;}
function deeperPage(s){const j=s.profileJourney,f=careerFamilies.find(f=>f.id===j.family);if(!f)return pathwaysPage(s);const qs=professionQuestions[f.id]||[],index=j.depthIndexes[f.id]||0,q=qs[index],picked=j.depth[f.id]?.[q.id]||[];return `${journeyProgress(3)}<div class="question-toolbar"><button class="text-link" data-action="journey-instructions">How to decide</button><a href="#/overview">Save & pause</a></div>${questionIntro(q.prompt)}<section class="profile-question deep-question multi-question"><p class="choice-instruction">Choose any that fit.</p><div class="profile-multi-grid">${q.options.map(o=>b('journey-deep-toggle',h(o.text),`data-id="${o.id}" aria-pressed="${picked.includes(o.id)}"`,true)).join('')}</div><div class="guide-actions mobile-step-actions">${index?b('journey-depth-back','← Back','',true):a('journey/pathways','← Pathways',true)}${b('journey-depth-next',picked.length?(index===qs.length-1?'See professions →':'Next →'):'Skip for now →')}</div></section>`;}
function lifestyleBadge(s,id){const fit=careerLifestyleFit(s,id);return fit?`<aside class="career-lifestyle-fit fit-${fit.key}"><strong>${h(fit.title)}</strong><p>${h(fit.copy)}</p>${trainingFundingNote(s,id)}</aside>`:'';}
function interestMatchPanel(row){const m=row.interestMatch;if(!m)return '';const label=m.status==='incomplete'?'Finish the interest questions first':m.status==='flat'?'Your interests are still open':m.status==='missing'?'Try the work before deciding':({'very-strong':'Your interests fit well',strong:'Your interests fit',overlap:'Some interests fit',different:'Your interests are different'})[m.key]||'Work to explore';return `<aside class="interest-fit fit-${m.key}"><strong>${row.basis==='tasks'?'You liked several parts of this job':h(label)}</strong>${row.basis==='tasks'?'<p>'+(m.r===null?'Your wider interests are still unclear.':m.key==='different'?'Your wider interests are different.':'Your wider interests are less similar.')+'</p>':''}${row.needsRoleDetail?'<p>Compare the health roles before choosing.</p>':''}${row.roleFocusElsewhere?'<p>You chose different duties in the follow-up questions.</p>':''}${row.routeConflict?'<p>This job needs a different training route than you chose.</p>':''}</aside>`;}
function careerMatchDetails(s,row){const m=row.interestMatch;return more('More info · why this came up',`${row.comparisonOnly?'<p>This job shares the tasks you liked. Your choices give more detail about another job, so keep this as an alternative to compare.</p>':''}${row.basis==='tasks'?'<p><strong>Repeated task interest</strong>: you liked several tasks linked to this job.</p>':''}${row.reasons.length?'<ul>'+row.reasons.map(t=>'<li>'+h(t)+'</li>').join('')+'<\/ul>':'<p>Read about the daily work and try a small part of it.</p>'}${row.fieldContrast?preferenceNotice(row.broad):''}${row.interestContrast||row.fieldContrast?'<p>Some tasks appeal to you, but earlier answers point elsewhere. Try the work before deciding.</p>':''}${row.strengths?.length?'<p><strong>Skills you have tried:</strong> '+row.strengths.slice(0,2).map(q=>h(skillLabels[q.id])).join(' · ')+'</p>':''}${careerScopeNotes(row.o.id).map(t=>'<p>'+h(t)+'</p>').join('')}${careerInsightsPanel(s,row.o,{compact:true})}<p>${m?.r===null?'Your answers do not give a clear interest comparison yet.':'We compare all six interest scores, then look at your work choices.'} This describes interests, not ability or your chance of success.</p>`);}

function careerCard(s,row){if(row.o.expandedDegree){const o=row.o;return `<article class="profession-card"><h3>${h(o.title)}</h3><p>${h(o.summary)}</p><p>${o.educationGroup==='graduate'?'Graduate / professional degree':'College · bachelor’s degree'}</p>${o.requiresExperience?'<p>Destination role: related experience is typically required.</p>':''}<p>Three distinct supported interests and strong whole-profile alignment.</p><p>${expandedPayEvidence(o.id)?'Sourced wage planning reference available; education funding still to review.':'Pay, costs and lifestyle: not assessed.'}</p>${a('journey/profession/'+o.id,'Explore this job →')}</article>`;}const o=row.o,paid=salaryProgression(o.id)?.paidTraining,firstStage=paid?.stageKey||'entry';return `<article class="profession-card"><header class="field-card-heading">${careerGlyph(o)}<h3>${h(careerTitle(o))}</h3></header><p class="career-card-work">${h(careerLanguage[o.id]?.[0]||'Learn about the daily work.')}</p>${educationBadges(o)}${interestMatchPanel(row)}${row.sharedWork?'<p class="shared-work-note"><strong>These tasks fit several jobs.</strong> Compare the daily work before choosing.</p>':''}${educationTradeoff(s,o)?'<p class="insight-tradeoff">'+h(educationTradeoff(s,o))+'</p>':''}${row.fieldContrast?'<p class="insight-tradeoff">You disliked some work in this field.</p>':''}<p><strong>Get started:</strong> ${h(careerEducationSummary(o))}</p>${o.id==='chef'?'<p>Cooking experience comes before leading a kitchen.</p>':''}<p class="profession-pay">${formatSalary(salaryAtStage(o.id,firstStage))}<span>${paid?(firstStage==='residency'?'First-year resident · published example':firstStage==='academy'?'Paid academy · published example':'First-period apprentice · published example'):'Estimated starting pay'} / year before tax</span></p>${salaryLifestyleLink(o.id,firstStage,'guided-career')}${paid?'<p>'+(firstStage==='residency'?'College and medical school come before paid residency.':'Paid training comes before qualified work.')+'</p>':''}${lifestyleBadge(s,o.id)}${careerMatchDetails(s,row)}${a('journey/profession/'+o.id,'Explore this job →')}</article>`;}
function workPreferences(s){const j=s.profileJourney;return contextQuestions.filter(q=>j.answers[q.id]!==undefined).map(q=>{const picked=Array.isArray(j.answers[q.id])?j.answers[q.id]:[j.answers[q.id]];return '<p><strong>'+h(q.prompt)+'</strong><br>'+q.options.filter(([id])=>picked.includes(id)).map(([,t])=>h(t)).join(' · ')+'</p>';}).join('');}
function professionsPage(s){const family=s.profileJourney.family,f=careerFamilies.find(f=>f.id===family),original=professionSuggestions(s,family),display=planMatchCandidates(s),r={...original,top:display.top,limited:!display.top.length},seen=new Set(),grouped=directions.filter(d=>f.paths.includes(d.id)).map(d=>({d,rows:r.rows.filter(row=>{if(seen.has(row.o.id)||!row.o.pathIds.includes(d.id))return false;seen.add(row.o.id);return true;})}));const remaining=r.rows.filter(row=>!seen.has(row.o.id));if(remaining.length)grouped.push({d:{title:'More health & helping professions'},rows:remaining});const preparationConflict=r.rows.some(row=>row.specificSupport===2&&row.routeConflict),alternatives=r.rows.filter(row=>row.supported&&!r.top.some(t=>t.o.id===row.o.id));return `${journeyProgress(3)}${intro('Your matches across fields',preparationConflict?'Compare your preparation routes.':r.top.length?'Jobs to explore.':r.status==='broad'?'Compare the work you liked.':r.taskLeads.length?'Start with the work you liked.':'Let’s get a feel for the work.',preparationConflict?'You liked the work but chose a different training route.':r.top.length?(r.top.some(row=>row.basis==='tasks'&&row.interestContrast)?'You liked these tasks. Your wider interests point elsewhere, so try the work before choosing.':'Start with the work you want to try.'):r.status==='broad'?'Your answers connect with several roles equally. We won’t pick three arbitrarily.':r.taskLeads.length?'Your task choices give you a place to start. Compare them with your wider interests.':'Your answers are still open. Read about a few roles before deciding.')}${original.status==='broad'&&original.supportedCount===0?'<aside class="match-note">Your latest field answers leave several possibilities open. We won’t pick three arbitrarily from those answers. Earlier work you explored remains available below.</aside>':''}${careerComparisonsPanel(s)}<section id="first-matches"><h2>${h(matchPresentation(s).label)}</h2><p>${h(matchPresentation(s).explanation)}</p>${r.top.length?'<div class="pathway-trio">'+r.top.map(row=>careerCard(s,row)).join('')+'</div>':''}</section>${pendingProfessionPanel(s)}${opportunitiesPanel(s,{compact:true})}${more('More info · how we suggest jobs','<p>These are ideas to explore, not promises of admission, ability, or success. We use your full interest profile and several work choices.</p>')}${r.top.length>1&&new Set(r.top.map(row=>[row.score,row.specificSupport,row.routeSupport].join(':'))).size===1?'<p>You liked similar tasks in these jobs. Compare their training and daily work.</p>':''}${alternatives.length?'<section class="task-led-options"><h2>More jobs to compare.</h2><p>Several jobs share the tasks you liked. These are alternatives, not lower ranks.</p><ul>'+alternatives.map(row=>'<li><a href="#/journey/profession/'+h(row.o.id)+'">'+h(row.o.finance?.title||row.o.title)+' →</a></li>').join('')+'</ul></section>':''}${r.status==='preference-conflict'?preferenceNotice(journeyFieldConnection(s,family)):''}${r.rows.some(row=>row.specificSupport===2&&row.routeConflict)?'<aside class="preference-conflict"><strong>Your work and preparation choices point to different roles.</strong><p>You liked '+r.rows.filter(row=>row.specificSupport===2&&row.routeConflict).map(row=>h(row.o.finance?.title||row.o.title)).join(' and ')+' work, but chose a different preparation route. Compare the routes before choosing.</p>'+b('journey-depth-jump','Compare preparation routes →','data-index="10"',true)+'</aside>':''}${family==='health'&&!r.top.length&&r.rows.some(row=>row.needsRoleDetail&&!row.roleFocusElsewhere&&!row.routeConflict&&row.score>=3&&row.interestMatch.eligible)?'<p>Several health jobs share these tasks. Compare the jobs before choosing.</p>'+b('journey-depth-jump','Compare the professional roles →','data-index="8"',true):''}${r.limited?'<p>You do not need to choose a profession yet. Try a small part of the work and come back.</p>':''}${r.taskLeads?.length?'<section class="task-led-options"><h2>'+(r.top.length?'Other work you wanted to try.':'Work you wanted to try.')+'</h2><p>Your choices connect with these tasks. Your wider interests are different or still unclear. Try the tasks before choosing.</p><div class="pathway-trio">'+r.taskLeads.map(row=>careerCard(s,row)).join('')+'</div></section>':''}${more('Your work preferences to compare',workPreferences(s)+'<p>These preferences guide what to ask and try. A preference does not establish ability or close a career door. Read each profession’s working-life section for occupation-level information.</p>')}<h2>Keep exploring this field.</h2>${grouped.filter(g=>g.rows.length).map(g=>more(h(g.d.title),'<div class="library-card-grid">'+g.rows.map(row=>careerCard(s,row)).join('')+'</div>')).join('')}<div class="guide-actions">${a('journey/deeper','← Revisit these questions',true)}${a('journey/pathways','Try another pathway →',true)}</div>`;}
export function profileJourneyPage(route,s){if(route==='journey/lifestyle-summary')return journeyProgress(0)+guidePage('guide/lifestyle-summary',s).replace('href="#/guide/paths"','href="#/journey/interest-intro"').replace('Find careers for this life →','Explore interests and careers →');const open=openExplorerPage(route,s);return open!==null?open:historicalProfileJourneyPage(route,s);}
// Retained renderer for versioned historical regression checks. Student routing uses the open explorer.
export function historicalProfileJourneyPage(route,s){if(route.startsWith('journey/discover'))return journeyProgress(2)+broadExplorationPage(s,route);if(route==='journey/expanded-matches')return resultsPlanPage(s);if(route.startsWith('journey/degree-check/'))return expandedCheckPage(s,route.split('/')[2]);const part=route.split('/')[1];if(part==='lifestyle')return journeyProgress(0)+guidePage('guide/lifestyle',s);if(part==='lifestyle-summary')return journeyProgress(0)+guidePage('guide/lifestyle-summary',s).replace('href="#/guide/paths"',profileComplete(s)?'href="#/journey/pathways"':'href="#/'+profileStartRoute(s)+'"').replace('Find careers for this life →',profileComplete(s)?'My pathways →':'Get to know me →');if(part==='profile-intro')return profileIntroductionPage(s);if(part==='profile-followups')return profileFollowupIntroductionPage();if(part==='profile-experience')return profileSectionIntroductionPage('skill',s);if(part==='profile-priorities')return profileSectionIntroductionPage('values',s);if(part==='profile-working-life')return profileSectionIntroductionPage('context',s);if(part==='profile')return profileQuestionPage(s);if(part==='profile-review')return profileReviewPage(s);if(part==='pathways')return pathwaysPage(s);if(part==='profession-intro')return professionIntroductionPage(s);if(part==='deeper')return deeperPage(s);if(part==='professions')return professionsPage(s);if(part==='check-career')return journeyProgress(3)+careerCheckPage(s,route.split('/')[2],route.split('/')[3]);if(part==='profession'){const id=route.split('/')[2],row=professionSuggestions(s).rows.find(r=>r.o.id===id);return journeyProgress(3)+simpleCareerPage(id,s,true,{journey:true,reasons:row?.reasons||[],differentClues:row?.interestContrast||row?.fieldContrast}).replaceAll('#/career/','#/journey/profession/');}if(part==='research')return researchPage();return pathwaysPage(s);}
export function journeyPlanContext(s){if(!s.profileJourney?.started)return '';const f=careerFamilies.find(f=>f.id===s.profileJourney.family);return `<section class="journey-plan-context"><h2>Change your plan anytime.</h2><p>${f?'Current pathway: '+h(f.title)+'. ':''}Keep what you learned. Choose a different direction when you want.</p>${pathwayProfileEvidence(s,f?.id).concerns.length>=2?'<p><strong>Some parts of this work may not appeal to you.</strong> Try the work before committing.</p>':''}${a('journey/pathways','My pathways',true)} ${a('journey/lifestyle-summary','My lifestyle picture',true)}${more('My interests & experience',profileSnapshot(s)+workPreferences(s)+(f?patternDetails(s,journeyFieldConnection(s,f.id)):''))}${Object.values(s.profileJourney.skills).some(skillExperienceNeedsSupport)?'<p><strong>New to this? Start small.</strong> Try a beginner-friendly lesson or a supervised demonstration. Skills grow with practice.</p>':''}</section>`;}
function researchPage(){return `${intro('BEHIND THE GUIDE','Get to know yourself. Try the work.','Your interests are a starting point, with room to change your mind.')}<section class="guide-input-panel"><h2>How suggestions take shape</h2><p>First, 60 O*NET® activities build your six-part interest profile.</p><p>Then, your everyday-work choices help us suggest pathways. More focused questions help compare professions.</p><p>Optional experience and work-style questions, your priorities, education choices, and Austin lifestyle add context. They do not change your interest scores.</p></section><section class="guide-input-panel"><h2>What a match means</h2><p>A suggestion is work worth exploring. It does not measure aptitude or predict admission, pay, or success.</p><p>The O*NET assessment has published research. Fieldguide’s added questions and combined guidance still need evaluation with students.</p>${more('Assessment source & license','<p>'+h(onetInstrument.attribution)+'</p><p>Official questions, response choices, and order are preserved. Fieldguide’s follow-ups are separate. USDOL/ETA does not endorse this guide.</p><p><a href="'+onetInstrument.sourceURL+'">Official question source ↗</a> · <a href="'+onetInstrument.licenseURL+'">License ↗</a></p>')}</section><p><a href="./developer.html">Developer: research, methods & calibration →</a></p>${a('overview','← My guide',true)}`;}

function profileReviewPage(s){const sections=[['Your interests',0,false],['Everyday work',1,true],['Your experience',2,true],['What matters to you',3,false],['Work style & education',4,true]];return journeyProgress(1)+intro('YOUR PROFILE','Review or add a little more.','Your answers stay saved. Extra detail is optional.')+profileSnapshot(s)+'<div class="field-group-grid">'+sections.map(([t,section,optional])=>'<article class="pathway-card"><h2>'+h(t)+'</h2>'+(optional?'<p>Optional extra detail.</p>':'')+b('journey-jump',optional?'Review or add answers →':'Review answers →','data-index="'+profileSectionStarts()[section]+'"')+'</article>').join('')+'</div><div class="guide-actions">'+a('journey/pathways','← My pathways',true)+'</div>';}
